// contractAssertStateZeroOnError asserts State returns zero alongside any error.
func contractAssertStateZeroOnError(
	tb testing.TB,
	c Contract,
) {
	tb.Helper()
	ctx, cancel := context.WithCancel(tb.Context())
	cancel()
	got, err := c.State(ctx)
	if err == nil {
		tb.Skip("State answered for a cancelled context, so this check has no error to inspect")
	}

	var zero string
	if got != zero {
		tb.Errorf("State must return the zero value alongside an error: got %+v, want %+v (err %v)",
			got, zero, err)
	}
}

